    internal static string GetEncodingName(string label)
    {
        if (label == null)
        {
            throw new ArgumentNullException("label");
        }

        return GetEncodingName(label.AsSpan());
    }

    internal static string GetEncodingName(ReadOnlySpan<char> label)
    {
        int start = 0;
        int end = label.Length;
        while (start < end && Ascii.IsHtmlWhitespace(label[start]))
        {
            start = start + 1;
        }

        while (end > start && Ascii.IsHtmlWhitespace(label[end - 1]))
        {
            end = end - 1;
        }

        ReadOnlySpan<char> normalized = label.Slice(start, end - start);
        int minimum = 0;
        int maximum = labels.Length - 1;
        while (minimum <= maximum)
        {
            int middle = minimum + (maximum - minimum) / 2;
            int comparison = Compare(normalized, labels[middle]);
            if (comparison == 0)
            {
                return names[middle];
            }

            if (comparison < 0)
            {
                maximum = middle - 1;
            }
            else
            {
                minimum = middle + 1;
            }
        }

        return "";
    }

    internal static int Compare(ReadOnlySpan<char> value, string label)
    {
        int count = value.Length < label.Length ? value.Length : label.Length;
        int index = 0;
        while (index < count)
        {
            char left = Ascii.ToLower(value[index]);
            char right = label[index];
            if (left < right)
            {
                return -1;
            }

            if (left > right)
            {
                return 1;
            }

            index = index + 1;
        }

        if (value.Length < label.Length)
        {
            return -1;
        }

        if (value.Length > label.Length)
        {
            return 1;
        }

        return 0;
    }
